import{_ as t,o as e,c as o,a2 as r}from"./chunks/framework.Crpw6aS5.js";const h=JSON.parse('{"title":"迪诺斯·约达努","description":"","frontmatter":{"title":"迪诺斯·约达努","date":"2026-04-13T00:00:00.000Z"},"headers":[],"relativePath":"04_people/迪诺斯·约达努.md","filePath":"04_people/迪诺斯·约达努.md"}'),l={name:"04_people/迪诺斯·约达努.md"};function n(i,a,s,_,p,d){return e(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="迪诺斯·约达努" tabindex="-1">迪诺斯·约达努 <a class="header-anchor" href="#迪诺斯·约达努" aria-label="Permalink to &quot;迪诺斯·约达努&quot;">​</a></h1><ul><li><strong>角色职位</strong>：伯克希尔·哈撒韦保险业务管理层</li><li><strong>与巴菲特关系</strong>：伯克希尔旗下科布县保险（Coburn &amp; Wilcox/National Indemnity）业务高管</li></ul><h2 id="主要事迹" tabindex="-1">主要事迹 <a class="header-anchor" href="#主要事迹" aria-label="Permalink to &quot;主要事迹&quot;">​</a></h2><p>迪诺斯·约达努是伯克希尔·哈撒韦保险业务体系中的重要管理者，主要负责科布县保险板块的运营。科布县保险与国家赔偿保险共同构成了伯克希尔保险帝国的双引擎，为集团提供着充裕的浮存金支持。</p><p>约达努在保险行业的专业背景深厚，对承保风险有着敏锐的判断力。在伯克希尔的保险业务框架中，每一位高管都需要在风险与收益之间找到精妙的平衡——既要接受足够的保费以积累浮存金，又不能以过低的价格承保导致亏损。约达努在这方面的表现为伯克希尔保险业务的稳健发展做出了重要贡献。</p><p>伯克希尔的保险业务之所以被视为全球保险业的标杆，很大程度上依赖于阿吉特·贾恩、米歇尔·罗斯曼等顶尖保险管理者，以及约达努这样专注于特定业务板块的专业人才。他们的集体智慧与纪律性，共同构筑了伯克希尔在保险领域难以复制的竞争优势。</p><h2 id="关键年份事件" tabindex="-1">关键年份事件 <a class="header-anchor" href="#关键年份事件" aria-label="Permalink to &quot;关键年份事件&quot;">​</a></h2><ul><li><strong>1990年代</strong>：担任伯克希尔科布县保险业务高管</li><li><strong>2000年代</strong>：继续负责该业务板块的管理运营</li><li><strong>近年</strong>：保持管理层职务，参与伯克希尔保险业务的持续增长</li></ul>',8)])])}const u=t(l,[["render",n]]);export{h as __pageData,u as default};
